mapper.select:
SELECT R.ROLE_ID
FROM TB_ROLE R
WHERE R.ROLE_CD = #{roleCode}

mapper.insert:
INSERT INTO TB_PERMISSION_ROLE_MAPPING ( PERM_ID, ROLE_ID ) SELECT P.PERM_ID, #{roleId} FROM TB_PERMISSION P WHERE P.PERM_ENABLED = 'Y' AND P.PERM_ID IN
#{permissionId}
AND NOT EXISTS ( SELECT 1 FROM TB_PERMISSION_ROLE_MAPPING PRM WHERE PRM.PERM_ID = P.PERM_ID AND PRM.ROLE_ID = #{roleId} )

INSERT INTO TB_ROLE_ASSIGNMENT ( ROLE_ASSIGN_ID, ROLE_ID, EMP_ID, SCOPE_TYPE_CD, SCOPE_ID, ENABLED ) SELECT (SELECT NVL(MAX(ROLE_ASSIGN_ID), 0) FROM TB_ROLE_ASSIGNMENT) + ROW_NUMBER() OVER (ORDER BY E.EMP_ID) AS ROLE_ASSIGN_ID, #{roleId} AS ROLE_ID, E.EMP_ID, #{scopeTypeCd} AS SCOPE_TYPE_CD, CASE WHEN #{scopeTypeCd} = 'SELF' THEN TO_CHAR(E.EMP_ID) ELSE #{scopeId} END AS SCOPE_ID, 'Y' AS ENABLED FROM TB_EMPLOYEE E WHERE E.ENABLED = 'Y' AND E.EMP_ID IN
#{empId}
AND NOT EXISTS ( SELECT 1 FROM TB_ROLE_ASSIGNMENT RA WHERE RA.ROLE_ID = #{roleId} AND RA.EMP_ID = E.EMP_ID AND RA.SCOPE_TYPE_CD = #{scopeTypeCd} AND NVL(RA.SCOPE_ID, '__NULL__') = NVL( CASE WHEN #{scopeTypeCd} = 'SELF' THEN TO_CHAR(E.EMP_ID) ELSE #{scopeId} END, '__NULL__' ) )

mapper.delete:
DELETE FROM TB_ROLE_ASSIGNMENT
WHERE ROLE_ID = #{roleId}
  AND EMP_ID IN

      #{empId}


      AND SCOPE_TYPE_CD = #{scopeTypeCd}


      AND SCOPE_ID = #{scopeId}


      AND SCOPE_ID = TO_CHAR(EMP_ID)
